<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\HasMany;
class InventoryProduct extends Model { protected $fillable=['sku','name','category','unit','purchase_price','sale_price','stock_quantity','stock_min','currency','description','is_active','barcode','location','track_stock']; protected $casts=['purchase_price'=>'decimal:2','sale_price'=>'decimal:2','is_active'=>'boolean','track_stock'=>'boolean']; public function movements():HasMany{return $this->hasMany(StockMovement::class);} public function orderLines():HasMany{return $this->hasMany(SalesOrderLine::class);} public function warehouseStocks():HasMany{return $this->hasMany(WarehouseStock::class);} public function lines():HasMany{return $this->hasMany(CommercialDocumentLine::class);} }
